import { useEffect } from "react";

const searchDelay = 500; // Delay to search for games after the user stops typing

export const Search = () => {
  const [searchQuery, setSearchQuery] = useState("");
  const [delayedQuery, setDelayedQuery] = useState("");

  useEffect(() => {
    const searchDelayHandler = setTimeout(() => {
      setDelayedQuery(searchQuery);
    }, searchDelay);

    return () => clearTimeout(searchDelayHandler);
  }, [searchQuery]);

  useEffect(() => {
    if (delayedQuery) {
      console.log("Searching for: ", delayedQuery);
    }
  }, [delayedQuery]); // Run when delayedQuery changes

  return (
    <div className="searchContainer">
      <input
        type="text"
        placeholder="Search Games..."
        className="searchInput"
        onChange={(e) => {
          setSearchQuery(e.target.value);
        }} 
      ></input>
    </div>
  );
}
